import{_ as e,o as t,c as l,ae as o}from"./chunks/framework.RRduUuAx.js";const u=JSON.parse('{"title":"アカウント削除の説明","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ja/help/account-deletion.md","filePath":"v1/ja/help/account-deletion.md"}'),i={name:"v1/ja/help/account-deletion.md"};function r(n,a,c,d,h,s){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="アカウント削除の説明" tabindex="-1">アカウント削除の説明 <a class="header-anchor" href="#アカウント削除の説明" aria-label="Permalink to &quot;アカウント削除の説明&quot;">​</a></h1><p>アカウント削除を行うと、このアカウントに紐づくクラウド上および本端末上のデータがすべて削除されます。実行前に影響を必ず確認してください。</p><h2 id="何が起こるか" tabindex="-1">何が起こるか <a class="header-anchor" href="#何が起こるか" aria-label="Permalink to &quot;何が起こるか&quot;">​</a></h2><ul><li>クラウドデータ：このアカウントのクラウド同期データが削除されます（帳簿、明細、カテゴリ、タグ等を含みます）。</li><li>ローカルデータ：現在の端末に保存されているこのアカウントのローカルデータが削除されます（オフラインデータを含みます）。</li><li>元に戻せません：削除完了後、データを復元することはできません。</li></ul><h2 id="サブスクリプションへの影響" tabindex="-1">サブスクリプションへの影響 <a class="header-anchor" href="#サブスクリプションへの影響" aria-label="Permalink to &quot;サブスクリプションへの影響&quot;">​</a></h2><p>アカウント削除は、サブスクリプションの有効期間に影響しません。</p><p>有料会員の場合、削除後に再ログインし、アプリ内の「購入を復元」をタップすることで会員状態を復元できます（App Store / Google Play の購読状態に依存します）。</p><h2 id="推奨" tabindex="-1">推奨 <a class="header-anchor" href="#推奨" aria-label="Permalink to &quot;推奨&quot;">​</a></h2><ul><li>データを残したい場合は、事前にアプリ内でエクスポート/バックアップ（提供されている場合）を行ってください。</li><li>削除後に再ログインすると新しい環境として扱われるため、再同期/再インポートが必要になる場合があります。</li></ul>',9)])])}const _=e(i,[["render",r]]);export{u as __pageData,_ as default};
